"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["46344"],{63706(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.sem_unanimidade_obrigatoria","status":422,"titulo":"O crit\xe9rio de unanimidade, em banca com mais de um integrante, declara o resultado sem unanimidade"},"descricao":{"codigo":"uniplus.selecao.banca.sem_unanimidade_obrigatoria","requisitos":["UNI-REQ-0275","UNI-REQ-0401"],"oQueAconteceu":["A banca decide por unanimidade (`unanimidade`), tem 2 ou mais integrantes e n\xe3o\\ndeclara o que vale quando a unanimidade n\xe3o \xe9 alcan\xe7ada. Com mais de um\\nintegrante, os votos podem divergir, e o edital precisa dizer a decis\xe3o nesse\\ncaso (UNI-REQ-0275). Sem o campo, a vota\xe7\xe3o dividida ficaria sem desfecho.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.semUnanimidade` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.semUnanimidade` na banca da etapa."],"comoResolver":["Informe no campo `semUnanimidade` o que o edital declara: `favoravel`,\\n`desfavoravel` ou `novaVotacao`. Fora da unanimidade, ou com 1 integrante, o campo\\nn\xe3o se aplica; ver\\n[valor para a unanimidade n\xe3o se aplica](/erros/uniplus.selecao.banca.sem_unanimidade_nao_se_aplica)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);